/**
 * Query is the read side of the syndication layer.
 *
 * Everything here is public and unauthenticated, which is a decision rather
 * than a default. An investor's whole complaint about a paper syndicate is that
 * the cap table is a spreadsheet somebody else holds: they cannot see what they
 * own, what the fees took, or who else is in.
 *
 * What is deliberately NOT here is a "every position this address holds"
 * query. A public index of private wealth keyed by person is a targeting list,
 * and the platform's own investors — diaspora, HNWIs, family offices — are
 * exactly the people it would target.
 */
export interface Query {
  /** Params returns the platform-wide ceilings. */
  Params(request: QueryParamsRequest): Promise<QueryParamsResponse>;
  /** Operators lists the admitted platform operators. */
  Operators(request: QueryOperatorsRequest): Promise<QueryOperatorsResponse>;
  /**
   * Investor reports whether an address has been onboarded, which is the
   * question a secondary buyer needs answered before they bid.
   */
  Investor(request: QueryInvestorRequest): Promise<QueryInvestorResponse>;
  /** Deal returns one syndication. */
  Deal(request: QueryDealRequest): Promise<QueryDealResponse>;
  /** DealByRef finds one by the platform's own reference. */
  DealByRef(request: QueryDealByRefRequest): Promise<QueryDealResponse>;
  /** Deals lists them. */
  Deals(request: QueryDealsRequest): Promise<QueryDealsResponse>;
  /** Commitments lists what has been committed to one deal. */
  Commitments(request: QueryCommitmentsRequest): Promise<QueryCommitmentsResponse>;
  /**
   * Entitlement is what one holder could claim right now, settled and
   * unsettled together — the number a statement would show, computed rather
   * than reported.
   */
  Entitlement(request: QueryEntitlementRequest): Promise<QueryEntitlementResponse>;
  /** Listings are the secondary market for one deal. */
  Listings(request: QueryListingsRequest): Promise<QueryListingsResponse>;
  /**
   * Documents are the papers one deal depends on: their digests, not their
   * contents. Public like everything else here, because an investor who cannot
   * see which agreements govern what they own is back in the spreadsheet the
   * platform exists to replace.
   */
  Documents(request: QueryDocumentsRequest): Promise<QueryDocumentsResponse>;
}

